193	    // runs before any key byte is written, so a file that cannot meet the
194	    // requirement never receives secret data.
195	    if unsafe { libc::fchmod(fd, 0o600) } != 0 {
196	        let e = std::io::Error::last_os_error();
197	        return Err(std::io::Error::new(
198	            e.kind(),
199	            format!(
200	                "cannot set key file permissions to 0600: {e} \
201	                 (filesystem does not support the required permissions)"
202	            ),
203	        ));
204	    }
205	
206	    let mut st: libc::stat = unsafe { std::mem::zeroed() };
207	    if unsafe { libc::fstat(fd, &mut st) } != 0 {
208	        // Without a fresh stat result the actual on-disk mode cannot be
209	        // confirmed, so the requirement cannot be met -- say so explicitly
210	        // rather than surface a bare errno string.
211	        let e = std::io::Error::last_os_error();
212	        return Err(std::io::Error::new(
213	            e.kind(),
214	            format!("cannot verify key file permissions are 0600: {e}"),
215	        ));
216	    }
217	
218	    // Exactly owner read/write, no group or other permissions of any kind.
219	    // This rejects 0400/0200/0000 (owner bits missing under a strict umask)
220	    // as well as any mode carrying group/other bits.
221	    if st.st_mode & 0o7777 != 0o600 {
222	        return Err(std::io::Error::new(
223	            std::io::ErrorKind::Other,
224	            format!(
225	                "cannot guarantee key file permissions 0600: \
226	                 filesystem reports mode 0{:04o}",
227	                st.st_mode & 0o7777
228	            ),
229	        ));
230	    }
231	    Ok(())
