346	            .expect("the key must eventually be written");
347	        let w = &events[first_write];
348	
349	        // Immediately before the first write call: mode is exactly 0600 and
350	        // size is still 0 -- no key byte preceded the confirmation.
351	        assert_eq!(w.mode().unwrap(), MODE_0600,
352	            "mode at first write must be exactly 0600 (umask {umask:04o})");
353	        assert_eq!(w.size().unwrap(), 0,
