359	        }).expect("fchmod(fd, 0600) must succeed");
360	        let confirm = first_index(&events, |e| {
361	            e.kind == "FSTAT"
362	                && e.ret() == Some(0)
363	                && e.mode() == Some(MODE_0600)
364	                && e.size() == Some(0)
365	        }).expect("an fstat must confirm exactly 0600 on an empty file");
366	        assert!(chmod < first_write, "fchmod must precede the first write");
367	        assert!(confirm < first_write, "confirmation must precede the first write");
368	
369	        // Every mode observation before the first write (birth included)
370	        // carries no group or other bits: the secret is never exposed while
371	        // open, even for an instant.
372	        for e in events.iter().take(first_write) {
373	            if e.kind == "BORN" || e.kind == "FSTAT" {
